/** Demo publication feed. Only public content updates participate; draft edits are excluded. */
export function latestPublic(records){return records.filter(x=>x.status==='published'&&Number.isFinite(Date.parse(x.contentUpdatedAt))).sort((a,b)=>Date.parse(b.contentUpdatedAt)-Date.parse(a.contentUpdatedAt)||a.id.localeCompare(b.id))[0]??null}
export const updates=[
 {id:'article-small',type:'文章',title:'一个人的项目，先做小，再做长。',summary:'从一个具体的问题开始。',href:'#/article/small',status:'published',contentUpdatedAt:'2026-09-18T10:00:00+08:00',mark:'&'},
 {id:'project-website',type:'作品',title:'个人空间：把表达与实践放在一起。',summary:'看看一个网站如何组织内容和价值。',href:'#/project/website',status:'published',contentUpdatedAt:'2026-09-19T10:00:00+08:00',mark:'↗'},
 {id:'product-website',type:'商品',title:'个人网站搭建手册',summary:'从定位、内容到上线的工作底稿。',href:'#/product/website',status:'published',contentUpdatedAt:'2026-09-20T10:00:00+08:00',mark:'+'},
 {id:'book-independent-site',type:'书籍',title:'从想法到自己的小站',summary:'表达、内容与独立实践。',href:'#/book/independent-site/introduction',status:'published',contentUpdatedAt:'2026-09-21T10:00:00+08:00',mark:'书'}
];
export function latestCard(){const x=latestPublic(updates);if(!x)return '';return `<a class="feature" href="${x.href}"><div class="feature-top"><span>最新更新 / ${x.type}</span><span class="label">示例${x.type}</span></div><h2>${x.title}</h2><span class="feature-mark" aria-hidden="true">${x.mark}</span><div class="feature-bottom"><span>${x.summary}</span><span>查看 ↗</span></div></a>`}
export function homeProjects(){return `<section class="home-projects"><div class="section-head"><div><span class="eyebrow">WORK / 把想法做出来</span><h2>文字之后，是具体的实践。</h2></div><a class="text-link" href="#/projects">全部作品 ↗</a></div><a class="home-project-card" href="#/project/website"><div class="home-project-art" aria-hidden="true"><span>文字</span><span>作品</span><span>小店</span></div><div><span class="label">设计中的项目</span><h3>个人空间</h3><p>一个承载表达、作品与交流的网站。看看它的功能如何组装，又为什么这样设计。</p><span class="text-link">了解这个作品 ↗</span></div></a></section>`}
export function bookCarousel(){return `<section class="home-books"><div class="section-head"><div><span class="eyebrow">BOOKS / 长篇写作</span><h2>把一个问题，写成一本书。</h2><p>沿着章节，把想法展开。</p></div><a class="text-link" href="#/books">全部书籍 ↗</a></div><div class="home-book-strip" aria-label="书籍卡片，可横向滚动" tabindex="0"><a href="#/book/independent-site/introduction" class="home-book blue-book"><span>示例书稿 / 可试读</span><h3>从想法<br>到自己的<br>小站</h3><p>表达、内容与独立实践</p><small>黄凌波 · 栏目演示</small><b>开始阅读 ↗</b></a><div class="home-book green-book" aria-label="第二本书占位，尚无书稿"><span>未来书稿位置 / 非真实书籍</span><h3>下一个<br>值得深写的<br>问题。</h3><p>书名与内容待本人提供</p><small>这里只展示书架的扩展方式</small><b>尚未开放阅读</b></div><div class="home-book pink-book" aria-label="第三本书占位，尚无书稿"><span>未来书稿位置 / 非真实书籍</span><h3>给还没<br>写下的想法，<br>留一页。</h3><p>书名与内容待本人提供</p><small>不代表已出版或正在销售</small><b>尚未开放阅读</b></div></div><div class="book-strip-controls"><span>左右滑动翻看 · 目前只有一份示例书稿</span><button data-book-step="-1" aria-label="向前浏览书籍">←</button><button data-book-step="1" aria-label="向后浏览书籍">→</button></div></section>`}
/** Book covers follow their distance from the shelf center; never tilt on touch or reduced motion. */
export function mountHome(root){
 const strip=root.querySelector('.home-book-strip');if(!strip)return()=>{};
 const c=new AbortController(),cards=[...strip.children],buttons=[...root.querySelectorAll('[data-book-step]')],quiet=matchMedia('(max-width:700px), (prefers-reduced-motion:reduce)');let frame=0;
 function draw(){frame=0;const max=strip.scrollWidth-strip.clientWidth;buttons.forEach(b=>{b.hidden=max<2;b.disabled=Number(b.dataset.bookStep)<0?strip.scrollLeft<16:strip.scrollLeft>max-16;});const r=strip.getBoundingClientRect();cards.forEach(el=>{const b=el.getBoundingClientRect(),d=Math.max(-1,Math.min(1,(b.left+b.width/2-r.left-r.width/2)/r.width));el.style.transform=quiet.matches?'none':`perspective(1000px) rotateY(${d*-12}deg) rotateZ(${d*2}deg)`;});}
 function schedule(){if(!frame)frame=requestAnimationFrame(draw)}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-book-step]');if(b)strip.scrollBy({left:Number(b.dataset.bookStep)*(cards[0].offsetWidth+parseFloat(getComputedStyle(strip).gap)),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})},{signal:c.signal});
 strip.addEventListener('scroll',schedule,{passive:true,signal:c.signal});window.addEventListener('resize',schedule,{signal:c.signal});quiet.addEventListener('change',schedule,{signal:c.signal});draw();return()=>{c.abort();cancelAnimationFrame(frame)};
}
